    "name": "Journal of the American Mathematical Society (JAMS)",
    "paper_title": "Ergodic Theory and Distribution of Rational Points on Homogeneous Varieties",
    "authors": "Prof. Pierre Deligne",
    "affiliations": "Department of Advanced Research, University Consortium; Institutional Center for Scientific Research",
    "publisher": "American Mathematical Society",
    "category": "Mathematics & Statistics",
    "kind": "Journal Article",
    "ranking": "Q1 Journals",
