    "bib_content": "@article{journal_of_mathematical_and_fundamental_sciences_ref1,\n  title={Bifurcation and Chaos Analysis of a Generalized Discrete Predator-Prey Model with Allee Effect},\n  author={Dr. Pudji Astuti and Dr. Edy Soewono},\n  journal={Journal of Mathematical and Fundamental Sciences},\n  volume={48},\n  number={3},\n  pages={100--125},\n  year={2024},\n  publisher={ITB Bandung},\n  doi={10.1016/j.journal_.2026.103865}\n}\n\n@article{vaswani2017attention,\n  title={Attention Is All You Need},\n  author={Vaswani, Ashish and Shazeer, Noam and Parmar, Niki and Uszkoreit, Jakob},\n  journal={Advances in Neural Information Processing Systems},\n  volume={30},\n  year={2017}\n}"
